-- Import des courriers arrivées 2021
-- Source : 2021.xlsx (feuille 2021).
--
-- Correspondance Excel -> table arrivees (formulaire arrivee/create.vue)
--   N° ARRIVEES            -> txt_numdordre (00001/jj-mm-aaaa)
--   DATE CREATION          -> dt_datearrivee
--   REFERENCE              -> txt_reference ; N° et date du courrier extraits
--   PRENOMS + NOMS         -> txt_prenomNom et txt_expediteur
--   objet                  -> txt_objet (libellé d'origine)
--   objet                  -> txt_designation (liste designationsParCategorie)
--   designation retenue    -> txt_categorie
--   N° TF                  -> txt_numTitreFoncier
--   ANCIEN N° TF           -> txt_numTitreMere s'il s'agit d'un titre, sinon situation
--   N° LOT                 -> txt_numLot
--   SUPERFICIE             -> txt_superficie
--   SITUATION/LOTISSEMENT  -> txt_lotissement
--   AGENTS TRAITEURS       -> txt_agenttraiteur
--   OBSERVATIONS           -> txt_observation
--   DATE DEPART            -> ajoutée à txt_observation
--   NICAD cité dans l'objet -> txt_NICAD
-- Une référence qui n'est qu'une date Excel est lue comme date du courrier.
--
-- Champs obligatoires absents du classeur :
--   txt_typecourrier = BE si l'objet commence par « BE », sinon Individuel
--   txt_nombrepiece  = 1
--   expéditeur ou agent vide -> Non renseigné
-- Référence absente : « <N°> du jj-mm-aaaa », comme le formulaire.
-- Références en doublon : suffixe [n° d'ordre].
-- N° d'arrivée en doublon : suffixe -2, -3…
-- Lignes importées : 2147
--
-- Répartition des catégories :
--    1994  Demande SERVICES
--      76  Réquisition - Instruction
--      60  Information
--      13  Convocation - Invitation
--       4  Réclamation - Signalement
-- Désignations :
--    1202  Morcellements
--     246  Demande de Cession définitive
--     177  Demande de Régularisation par voie de Bail
--     128  Demande de situation foncière
--      75  Instruction à suivre
--      56  Demande de délimitation
--      45  Demande d'états des lieux
--      33  Transmission lettre
--      27  Demande de terrain/Echange
--      23  Demande de CIC
--      17  Autorisation de lotir
--      16  Réquisition d'immatriculation
--      16  Duplication de CIC
--      15  Demande d'extraits de plan
--      12  Tribunal
--       8  Document administratif
--       7  Décision - Arrêté
--       6  Réunion
--       5  Autres
--       5  Réceptions de lotissements
--       4  Circulaire
--       2  Plainte
--       2  Demande d'attestation du Cadastre
--       2  Autorisation de construction
--       2  Litiges
--       2  Formation
--       2  Demande d'évaluation
--       2  Atelier
--       2  Dénonciation
--       1  Visite de site
--       1  Notes de services
--       1  Réquisition matériel
--       1  Cérémonie
--       1  Audience Publique
--       1  Rapport
--       1  Note de service
--       1  Lettre

SET NAMES utf8mb4;

START TRANSACTION;







COMMIT;
